package com.alsafa.native4;
import android.app.Activity;import android.os.Bundle;import android.view.*;import android.widget.*;import com.alsafa.native4.core.*;import java.text.*;import java.util.*;
public final class HandoverActivity extends Activity{private CoreDb db;private Native4Services services;private LinearLayout list;private TextView status;private Spinner dateFilter,statusFilter;
@Override public void onCreate(Bundle s){super.onCreate(s);setContentView(R.layout.activity_handover);db=new CoreDb(this);services=new Native4Services(db,"native4-android-alpha");list=findViewById(R.id.repairList);status=findViewById(R.id.status);dateFilter=findViewById(R.id.repairDateFilter);statusFilter=findViewById(R.id.repairStatusFilter);dateFilter.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"اليوم","آخر 7 أيام","كل التواريخ"}));statusFilter.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,new String[]{"غير المسلّمة","قيد الصيانة","بانتظار القطعة","جاهز للاستلام","مسلّمة حديثًا","الكل"}));android.widget.AdapterView.OnItemSelectedListener l=new android.widget.AdapterView.OnItemSelectedListener(){public void onItemSelected(android.widget.AdapterView<?> p,View v,int pos,long id){refresh();}public void onNothingSelected(android.widget.AdapterView<?> p){}};dateFilter.setOnItemSelectedListener(l);statusFilter.setOnItemSelectedListener(l);findViewById(R.id.pageBack).setOnClickListener(v->finish());findViewById(R.id.refreshRepairs).setOnClickListener(v->refresh());refresh();}
private void refresh(){list.removeAllViews();try{long now=System.currentTimeMillis(),from=0,to=0;Calendar cal=Calendar.getInstance();cal.set(Calendar.HOUR_OF_DAY,0);cal.set(Calendar.MINUTE,0);cal.set(Calendar.SECOND,0);cal.set(Calendar.MILLISECOND,0);if(dateFilter.getSelectedItemPosition()==0){from=cal.getTimeInMillis();to=from+86400000L;}else if(dateFilter.getSelectedItemPosition()==1){to=now+1;from=now-7L*86400000L;}String[] fs={"OPEN","IN_PROGRESS","WAITING_PART","READY","RECENT_DELIVERED","ALL"};String filter=fs[Math.max(0,statusFilter.getSelectedItemPosition())];List<RepairWorkflowStore.OpenRepair> rows;if("OPEN".equals(filter)){rows=new ArrayList<>();for(RepairWorkflowStore.OpenRepair r:services.repairs.repairsForView("ALL",from,to))if(!"DELIVERED".equals(r.status))rows.add(r);}else rows=services.repairs.repairsForView(filter,from,to);status.setText("العمليات المعروضة: "+rows.size());for(RepairWorkflowStore.OpenRepair r:rows)addRow(r);if(rows.isEmpty())status.setText("لا توجد عمليات مطابقة للفلاتر الحالية");}catch(Exception e){status.setText("تعذر تحميل الصيانات: "+msg(e));}}
private void addRow(RepairWorkflowStore.OpenRepair r){LinearLayout box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(12),dp(10),dp(12),dp(10));box.setBackgroundResource(R.drawable.alsafa_card);TextView t=new TextView(this);t.setGravity(Gravity.END);t.setText((r.invoiceNo==null?"":r.invoiceNo)+(r.customer.isEmpty()?"":" — "+r.customer)+"\n"+r.watch+"\n"+date(r.updatedAt)+" — الحالة: "+label(r.status)+" — "+String.format(Locale.US,"%.2f",r.total)+" "+r.currency);box.addView(t);if(!"DELIVERED".equals(r.status)){LinearLayout actions=new LinearLayout(this);actions.setOrientation(LinearLayout.HORIZONTAL);Button ready=new Button(this);ready.setText("جاهز");ready.setEnabled(!"READY".equals(r.status));ready.setOnClickListener(v->set(r,"READY"));Button delivered=new Button(this);delivered.setText("✓ تحصيل / تسليم");delivered.setEnabled("READY".equals(r.status));delivered.setOnClickListener(v->new RepairDeliveryDialog(this,services,status).show(r.repairId));actions.addView(ready,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));actions.addView(delivered,new LinearLayout.LayoutParams(0,ViewGroup.LayoutParams.WRAP_CONTENT,1f));box.addView(actions);}LinearLayout.LayoutParams lp=new LinearLayout.LayoutParams(-1,-2);lp.setMargins(0,dp(6),0,dp(6));list.addView(box,lp);}
private void set(RepairWorkflowStore.OpenRepair r,String s){try{services.repairs.setStatus(r.repairId,s);Native4BackgroundSync.request(this);status.setText("✓ تم تحديث حالة الصيانة");refresh();}catch(Exception e){status.setText("تعذر تحديث الصيانة: "+msg(e));}}
private int dp(int v){return Math.round(v*getResources().getDisplayMetrics().density);}private static String label(String s){if("DELIVERED".equals(s))return "مسلّمة";if("READY".equals(s))return "جاهز للاستلام";if("WAITING_PART".equals(s))return "بانتظار القطعة";if("IN_PROGRESS".equals(s)||"RECEIVED".equals(s))return "قيد الصيانة";return s;}private static String date(long x){return new SimpleDateFormat("yyyy-MM-dd HH:mm",Locale.US).format(new Date(x));}private static String msg(Exception e){return e.getMessage()==null?e.getClass().getSimpleName():e.getMessage();}}
